CREATE TABLE company(id INTEGER PRIMARY KEY,name TEXT NOT NULL,legal_form TEXT NOT NULL,business_type TEXT NOT NULL,currency TEXT NOT NULL,decimals INTEGER NOT NULL DEFAULT 2,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles(user_id INTEGER NOT NULL REFERENCES users(id),role_id INTEGER NOT NULL REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id INTEGER NOT NULL REFERENCES roles(id),permission TEXT NOT NULL,PRIMARY KEY(role_id,permission));
CREATE TABLE audit_log(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT NOT NULL,model TEXT NOT NULL,record_id INTEGER,old_value TEXT,new_value TEXT,source_ip TEXT,created_at TEXT NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY,scope TEXT NOT NULL,key TEXT NOT NULL,value TEXT,locked_after_first_posting INTEGER DEFAULT 0,UNIQUE(scope,key));
CREATE TABLE sequence_definitions(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,prefix TEXT DEFAULT '',padding INTEGER DEFAULT 4,next_number INTEGER DEFAULT 1);
CREATE TABLE partners(id INTEGER PRIMARY KEY,name TEXT NOT NULL,type TEXT DEFAULT 'company',tax_id TEXT UNIQUE,phone TEXT,email TEXT,active INTEGER DEFAULT 1,version INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,sku TEXT UNIQUE,product_type TEXT DEFAULT 'storable',sale_price INTEGER DEFAULT 0,active INTEGER DEFAULT 1,version INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,active INTEGER DEFAULT 1);
CREATE TABLE fiscal_periods(id INTEGER PRIMARY KEY,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE journals(id INTEGER PRIMARY KEY,reference TEXT UNIQUE NOT NULL,journal_date TEXT NOT NULL,period_id INTEGER REFERENCES fiscal_periods(id),memo TEXT,status TEXT NOT NULL DEFAULT 'draft',created_by INTEGER,posted_by INTEGER,posted_at TEXT);
CREATE TABLE journal_lines(id INTEGER PRIMARY KEY,journal_id INTEGER NOT NULL REFERENCES journals(id),account_id INTEGER NOT NULL REFERENCES accounts(id),partner_id INTEGER REFERENCES partners(id),debit INTEGER NOT NULL DEFAULT 0,credit INTEGER NOT NULL DEFAULT 0,memo TEXT,source_type TEXT,source_id INTEGER);
